(function () {
  'use strict';
  const chunkSet = {"title":"Story Elements","topic":"Reading Comprehension","questions":[{"id":"reading-comprehension-story-elements-q0101","version":3,"contentHash":"sha256:bfa0feda3008def60ca7f64553378ff019e6b14e93c2a9019af842d7c6221423","question":"Read the story. Grade 4 foundation story: Omar was at the computer lab when his slideshow disappeared when the program froze. Omar he checked the autosave folder and rebuilt two missing slides from his notes. In the end, his presentation was ready before class ended.\n\nWhich word best describes Omar?","choices":["careless","determined","boastful","impatient"],"correct":1,"studyAid":{"definition":"Character traits are qualities that describe how a person acts or thinks. You find them by looking at how a character behaves when they face a problem.","example":"If someone shares their lunch, they are generous. If someone waits for their turn without complaining, they are patient.","strategyClue":"Look at the actions the person takes when they hit a challenge in the story. Ask yourself, 'What do these actions tell me about the kind of person they are?'","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: determined. Omar showed determination by not giving up when his work disappeared. Instead of quitting, he took the time to check the autosave folder and rewrite his missing slides.","incorrect":[{"choice":"careless","category":"incorrect character trait","reason":"Someone who is careless makes messy mistakes. Omar worked hard to fix his problem, which shows he actually cares about his presentation."},"",{"choice":"boastful","category":"incorrect character trait","reason":"A boastful person talks about themselves too much to brag. There is no evidence in the story that Omar bragged about his work."},{"choice":"impatient","category":"incorrect character trait","reason":"An impatient person gives up quickly when things get difficult. Because Omar stayed to rebuild his slides, he showed patience rather than impatience."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["story elements","character","setting","plot"],"standards":["RL.2-6.3"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-story-elements","sequence":101,"skillIds":[],"standardIds":["RL.2-6.3"]}},{"id":"reading-comprehension-story-elements-q0102","version":3,"contentHash":"sha256:3df759f9b48ec450dfa7cd46c3775a3e42d40ea0e77cc632f1a0d80b2de9bf36","question":"Read the story. Grade 4 foundation story: Nora was at the neighborhood sidewalk when an elderly neighbor struggled to carry groceries up the steps. Nora Nora asked permission, carried two light bags, and held the gate open. In the end, the neighbor thanked her and invited her to pick tomatoes later.\n\nWhat is the story's main problem?","choices":["Nora cannot remember anyone's name.","Nora wants to leave the setting before anything happens.","an elderly neighbor struggled to carry groceries up the steps","The story has no problem to solve."],"correct":2,"studyAid":{"definition":"The 'main problem' (or conflict) is the challenge or obstacle a character faces that drives the action of the story.","example":"A lost puppy needs a home; a student forgets their homework and must find a way to finish it; a traveler gets stuck in the rain without an umbrella.","strategyClue":"Look for the sentence where someone experiences a difficulty or a need for help. The problem is usually the reason the main character takes action.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: an elderly neighbor struggled to carry groceries up the steps. A main problem in a story is the conflict or challenge that a character faces. In this story, the neighbor having difficulty carrying heavy items is the specific challenge that prompts Nora to help.","incorrect":[{"choice":"Nora cannot remember anyone's name.","category":"unsupported plot detail","reason":"The story never mentions Nora struggling with names; this is not a problem that appears in the text."},{"choice":"Nora wants to leave the setting before anything happens.","category":"contradictory plot detail","reason":"Nora actually stays to help the neighbor, so this statement goes against what the character does in the story."},"",{"choice":"The story has no problem to solve.","category":"misidentifying plot structure","reason":"Most stories have a central challenge. If you look at the neighbor's difficulty carrying bags, you can identify a clear moment where help is needed."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["story elements","character","setting","plot"],"standards":["RL.2-6.3"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-story-elements","sequence":102,"skillIds":[],"standardIds":["RL.2-6.3"]}},{"id":"reading-comprehension-story-elements-q0103","version":3,"contentHash":"sha256:43e373fd4f3ba8c63ec19935960b39ff68f25e29a9e75780b94411881dd56cce","question":"Read the story. Grade 4 foundation story: Ben was at the chess club table when he lost three games in a row. Ben he asked his opponent to show the move that trapped his queen. In the end, he used the lesson to avoid the trap in the next game.\n\nWhere does the story mainly take place?","choices":["at a train station","inside a grocery store","on a mountain trail","the chess club table"],"correct":3,"studyAid":{"definition":"The setting of a story tells you where and when the events take place. Look for nouns in the first few sentences that describe a place.","example":"If the story says 'The knight rode through the dark forest,' the setting is a forest. If it says 'She sat at her desk,' the setting is a classroom or office.","strategyClue":"Scan the first sentence of the paragraph for location words or prepositions like 'at,' 'in,' or 'on' that tell you where the character is standing or sitting.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: the chess club table. The first sentence directly states, 'Ben was at the chess club table,' which identifies the specific location of the events in the story.","incorrect":[{"choice":"at a train station","category":"incorrect story setting","reason":"The text never mentions a train station; the setting is clearly defined by the game of chess being played at a specific table."},{"choice":"inside a grocery store","category":"incorrect story setting","reason":"There is no mention of shopping or grocery items. The context of 'chess games' and a 'queen' piece belongs in a chess club, not a store."},{"choice":"on a mountain trail","category":"incorrect story setting","reason":"A mountain trail is an outdoor location, but the story mentions a 'table' and indoor game mechanics that would not be found on a trail."},""]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["story elements","character","setting","plot"],"standards":["RL.2-6.3"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-story-elements","sequence":103,"skillIds":[],"standardIds":["RL.2-6.3"]}},{"id":"reading-comprehension-story-elements-q0104","version":3,"contentHash":"sha256:dc2bc1360fe8ba87e585059a3a443056278529c7bef9ecf4d33fa25e429c3a80","question":"Read the story. Grade 4 foundation story: Talia was at the school hallway after dismissal when she found a wallet with lunch money and a student ID. Talia she took it to the office before leaving for practice. In the end, the owner got the wallet back before the buses left.\n\nHow is the problem resolved?","choices":["the owner got the wallet back before the buses left","Talia decides the problem is impossible.","An adult solves the problem without the character doing anything.","The story ends before the problem is addressed."],"correct":0,"studyAid":{"definition":"The resolution of a story is the final outcome where the main problem is solved or the situation is explained.","example":"Problem: A lost key. Resolution: The character finds it in their pocket. Problem: A broken vase. Resolution: The child tells the truth and helps clean it up.","strategyClue":"Look at the very last sentence or paragraph of the text. Ask yourself, 'What is the final status of the thing that was lost or broken?'","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: the owner got the wallet back before the buses left. This sentence from the final paragraph clearly explains the resolution, confirming that the lost item was returned to its rightful owner.","incorrect":["",{"choice":"Talia decides the problem is impossible.","category":"misunderstanding story events","reason":"This is incorrect because Talia takes action by bringing the wallet to the office, which leads to the owner getting it back."},{"choice":"An adult solves the problem without the character doing anything.","category":"ignoring character actions","reason":"This is incorrect because Talia is the character who finds the wallet and turns it in to the office, directly causing the problem to be solved."},{"choice":"The story ends before the problem is addressed.","category":"missing story resolution","reason":"This is incorrect because the final sentence of the story states exactly how the problem of the lost wallet was solved."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["story elements","character","setting","plot"],"standards":["RL.2-6.3"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-story-elements","sequence":104,"skillIds":[],"standardIds":["RL.2-6.3"]}},{"id":"reading-comprehension-story-elements-q0105","version":4,"contentHash":"sha256:c4120ca52622415c2feaa09d9f45d0b04c84ed019472471234f4b3bde22ae8c9","question":"Read the story. Grade 4 foundation story: Diego was at the creek behind the park when he saw that stepping stones had shifted after heavy rain. Diego he warned younger children to use the bridge and told a ranger. In the end, the crossing was closed until it could be repaired.\n\nWhat most likely motivates Diego's actions?","choices":["Diego wants to make the problem worse.","He wanted others to stay safe.","Diego hopes nobody notices the problem.","Diego is trying to avoid helping anyone."],"correct":1,"studyAid":{"definition":"To find a character's motivation, look at their actions and think about what goal they are trying to achieve through those choices.","example":"A student returns a lost wallet to the office because they are honest; a student helps a friend study because they are kind.","strategyClue":"Ask yourself, 'Why would someone take these specific actions?' Look for clues in the text that show the result the character is working toward.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: He wanted others to stay safe. Diego's actions—warning the younger children and notifying a ranger—show that he is concerned about the well-being of others and wants to prevent an accident.","incorrect":[{"choice":"Diego wants to make the problem worse.","category":"misunderstanding character intent","reason":"Warning others and telling a ranger is a helpful act meant to fix the danger, not increase it."},"",{"choice":"Diego hopes nobody notices the problem.","category":"ignoring stated actions","reason":"If he wanted the problem to go unnoticed, he would not have taken the time to warn the younger children or report it to an official."},{"choice":"Diego is trying to avoid helping anyone.","category":"contradictory evidence","reason":"Taking action by warning others and notifying an adult is the opposite of avoiding help; these are clear signs of being responsible and helpful."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["story elements","character","setting","plot"],"standards":["RL.2-6.3"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-story-elements","sequence":105,"skillIds":[],"standardIds":["RL.2-6.3"]}},{"id":"reading-comprehension-story-elements-q0106","version":3,"contentHash":"sha256:9b184b6075b0ba20c7835dc589c91488c1ebaa7b4d97329b5059c79812ae65ba","question":"Read the story. Grade 4 developing story: Lena was at the classroom supply table when her group's poster tore right before the science fair. Lena felt the pressure of the moment, but she calmly taped the back, asked for a spare sheet, and divided the repair jobs. In the end, the group finished on time.\n\nWhich word best describes Lena?","choices":["boastful","careless","resourceful","impatient"],"correct":2,"studyAid":{"definition":"To identify a character trait, look at what the character says, thinks, and does in a difficult situation.","example":"If a character shares their lunch with someone who forgot theirs, they might be 'generous.' If they fall down and try again without complaining, they might be 'determined.'","strategyClue":"Focus on Lena's actions: She solved a problem and led her team. Match these specific actions to the meaning of each choice to see which one fits a problem-solver.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: resourceful. Lena showed she was resourceful by finding a way to fix the poster quickly and organizing her group to finish on time despite the pressure.","incorrect":[{"choice":"boastful","category":"incorrect character trait","reason":"Being boastful means bragging about oneself. Lena was focused on fixing the problem, not talking about how great she was."},{"choice":"careless","category":"incorrect character trait","reason":"Someone who is careless makes mistakes by not paying attention. Lena was careful and thoughtful when she taped the poster and assigned jobs."},"",{"choice":"impatient","category":"incorrect character trait","reason":"An impatient person gets upset when they have to wait or things go wrong. The story says Lena remained calm under pressure, which is the opposite of being impatient."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["story elements","character","setting","plot"],"standards":["RL.2-6.3"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-story-elements","sequence":106,"skillIds":[],"standardIds":["RL.2-6.3"]}},{"id":"reading-comprehension-story-elements-q0107","version":3,"contentHash":"sha256:0988faff9563fcba72382ce81c50ba9d3812e8fc1b737f0fb4bb7982da943529","question":"Read the story. Grade 4 developing story: Mateo was at the school bus line when a younger student dropped a folder and papers scattered. Mateo felt the pressure of the moment, but Mateo stepped out of line, gathered the papers, and helped sort them by subject. In the end, the younger student smiled and found the missing homework.\n\nWhat is the story's main problem?","choices":["The story has no problem to solve.","Mateo wants to leave the setting before anything happens.","Mateo cannot remember anyone's name.","a younger student dropped a folder and papers scattered"],"correct":3,"studyAid":{"definition":"The main problem of a story is the conflict or challenge that the characters must face or overcome to reach the end.","example":"A character loses their library book, or a rainstorm ruins a planned picnic.","strategyClue":"Look for the moment in the story where something goes wrong or a character is stopped from doing what they wanted to do. Ask yourself: 'What incident forces the characters to take action?'","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: a younger student dropped a folder and papers scattered. The main problem is the conflict or obstacle that happens in a story. When the student drops their materials and papers scatter, it creates a situation that needs to be fixed.","incorrect":[{"choice":"The story has no problem to solve.","category":"misidentifying plot structure","reason":"Every story has a conflict or a problem. If nothing went wrong, there would be no reason for Mateo to step out of line and help."},{"choice":"Mateo wants to leave the setting before anything happens.","category":"misinterpreting character actions","reason":"This does not match the story, as Mateo actually chooses to stay and help the younger student rather than leave."},{"choice":"Mateo cannot remember anyone's name.","category":"unsupported plot detail","reason":"The story never mentions names or Mateo having trouble remembering them. This is not a problem mentioned in the text."},""]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["story elements","character","setting","plot"],"standards":["RL.2-6.3"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-story-elements","sequence":107,"skillIds":[],"standardIds":["RL.2-6.3"]}},{"id":"reading-comprehension-story-elements-q0108","version":3,"contentHash":"sha256:9d423ab6c8065e6945b88ba1d103c2106a38f1645cdc3e45cb754f12c1990dd5","question":"Read the story. Grade 4 developing story: Priya was at the community garden when her bean plants wilted after several hot days. Priya felt the pressure of the moment, but she checked the soil, moved mulch around the stems, and changed the watering schedule. In the end, new green leaves appeared the next week.\n\nWhere does the story mainly take place?","choices":["the community garden","inside a grocery store","on a mountain trail","at a train station"],"correct":0,"studyAid":{"definition":"The setting is the time and place where a story's events happen. Authors often provide clues early in the text to help readers identify the location.","example":"If a story talks about sand and waves, the setting is a beach. If it mentions desks and a chalkboard, the setting is a classroom.","strategyClue":"Scan the first sentence of the paragraph for location words or prepositions that describe where the main character is standing.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: the community garden. The text explicitly states at the very beginning that Priya was 'at the community garden' when she observed her bean plants wilting.","incorrect":["",{"choice":"inside a grocery store","category":"setting misidentification","reason":"The story mentions bean plants, soil, and mulch, which are things found in a garden, not a store where food is already picked."},{"choice":"on a mountain trail","category":"setting misidentification","reason":"While mountains are outdoors, the mention of 'watering schedules' and 'bean plants' indicates a place where gardening occurs, not a trail."},{"choice":"at a train station","category":"setting misidentification","reason":"A train station is for transportation, but the text focuses entirely on plants and soil care in a garden environment."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["story elements","character","setting","plot"],"standards":["RL.2-6.3"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-story-elements","sequence":108,"skillIds":[],"standardIds":["RL.2-6.3"]}},{"id":"reading-comprehension-story-elements-q0109","version":3,"contentHash":"sha256:eb46e88d767d7f4130f5ef08c3a6eb2170367fcfdda2064fef137f9827b9d47c","question":"Read the story. Grade 4 developing story: Noah was at the music room when he kept missing the same measure during recorder practice. Noah felt the pressure of the moment, but he slowed the song down, clapped the rhythm, and practiced four notes at a time. In the end, he played the measure correctly during rehearsal.\n\nHow is the problem resolved?","choices":["Noah decides the problem is impossible.","he played the measure correctly during rehearsal","An adult solves the problem without the character doing anything.","The story ends before the problem is addressed."],"correct":1,"studyAid":{"definition":"A problem is resolved when the main character takes action or changes their approach to reach a successful conclusion.","example":"Problem: A lost key. Resolution: Retracing steps to find it under the couch.","strategyClue":"Look for the sentence near the end of the text that describes the outcome of the character's actions to see how the conflict was fixed.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: he played the measure correctly during rehearsal. The story explicitly states that by breaking the song down and practicing small parts, Noah succeeded in the end.","incorrect":[{"choice":"Noah decides the problem is impossible.","category":"misreading text","reason":"This is incorrect because Noah does not give up. Instead, he uses specific strategies like clapping the rhythm to overcome the challenge."},"",{"choice":"An adult solves the problem without the character doing anything.","category":"incorrect plot summary","reason":"The story shows Noah taking charge of his own learning by slowing down the song and practicing. He solves the problem himself, not an adult."},{"choice":"The story ends before the problem is addressed.","category":"ignoring story outcome","reason":"The text provides a clear conclusion by stating that Noah played the measure correctly after his practice session."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["story elements","character","setting","plot"],"standards":["RL.2-6.3"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-story-elements","sequence":109,"skillIds":[],"standardIds":["RL.2-6.3"]}},{"id":"reading-comprehension-story-elements-q0110","version":3,"contentHash":"sha256:5f795ac19caf536054c70f2227541b4acdbb1a3c1a52faa0cb21f2fe1a97bc3a","question":"Read the story. Grade 4 developing story: Ari was at the lunch table when two friends argued about who should choose the game at recess. Ari felt the pressure of the moment, but Ari suggested each friend pick one round and then vote on a final round. In the end, both friends agreed and the argument ended.\n\nWhat most likely motivates Ari's actions?","choices":["Ari hopes nobody notices the problem.","Ari wants to make the problem worse.","Ari wanted both friends to feel heard.","Ari is trying to avoid helping anyone."],"correct":2,"studyAid":{"definition":"To find a character's motivation, look at what they do and the result of their actions. Think about whether their choice makes the situation better or worse.","example":"If a character shares their snack, they are motivated by kindness. If a character runs away from a chore, they are motivated by avoidance.","strategyClue":"Look at the specific solution Ari proposed and ask yourself, 'What does this solution tell me about how Ari wants the friends to feel at the end?'","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: Ari wanted both friends to feel heard. Ari's suggestion to play one round chosen by each friend shows that Ari values fairness and wants to find a compromise that makes both friends happy.","incorrect":[{"choice":"Ari hopes nobody notices the problem.","category":"misreading social cues","reason":"Ari actively steps in to offer a solution, which shows that Ari is not trying to hide or ignore the argument."},{"choice":"Ari wants to make the problem worse.","category":"misinterpreting character goals","reason":"Ari's suggestion of a compromise helps end the argument, rather than making it more difficult or heated."},"",{"choice":"Ari is trying to avoid helping anyone.","category":"misinterpreting helpfulness","reason":"Ari suggests a fair voting system, which is a helpful way to solve the conflict instead of staying out of it."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["story elements","character","setting","plot"],"standards":["RL.2-6.3"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-story-elements","sequence":110,"skillIds":[],"standardIds":["RL.2-6.3"]}},{"id":"reading-comprehension-story-elements-q0111","version":3,"contentHash":"sha256:0561aa7f42ea5168129ca24d6eb3af6098afe84bfcb48ef77d93ecbb87d8250d","question":"Read the story. Grade 4 developing story: Sofia was at the school art show when she worried that her painting looked different from everyone else's. Sofia felt the pressure of the moment, but she listened as visitors asked about her unusual colors and bold shapes. In the end, she began to feel proud of her own style.\n\nWhich word best describes Sofia?","choices":["impatient","careless","boastful","creative"],"correct":3,"studyAid":{"definition":"Character traits are qualities that define how a person acts or feels. To find the right trait, look for evidence in the text that matches a character's actions or thoughts.","example":"If a character helps a friend, they are 'kind'. If they try new things, they are 'adventurous'.","strategyClue":"Highlight the words in the story that describe the character's art or feelings, then ask yourself which adjective best matches those specific descriptions.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: creative. The text describes Sofia using 'unusual colors' and 'bold shapes' to develop her 'own style,' which demonstrates the imagination and originality associated with being creative.","incorrect":[{"choice":"impatient","category":"incorrect trait identification","reason":"There is no evidence in the story that Sofia is rushing or frustrated with waiting. She is focused on her art and the visitors' feedback rather than time."},{"choice":"careless","category":"incorrect trait identification","reason":"Careless means not paying attention to detail. Sofia's careful use of 'unusual colors' and 'bold shapes' suggests she is thoughtful about her work, not careless."},{"choice":"boastful","category":"incorrect trait identification","reason":"Boastful means bragging about oneself. The story shows Sofia feeling worried and then proud of her style, but she never talks about herself in an arrogant way."},""]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["story elements","character","setting","plot"],"standards":["RL.2-6.3"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-story-elements","sequence":111,"skillIds":[],"standardIds":["RL.2-6.3"]}},{"id":"reading-comprehension-story-elements-q0112","version":3,"contentHash":"sha256:4be498115f826da4dcc953ab92885f2837dde0628b556f24757954778a861ade","question":"Read the story. Grade 4 developing story: Evan was at the soccer field when his team was losing and he had not scored. Evan felt the pressure of the moment, but he passed to a teammate who had a clear shot instead of kicking from a bad angle. In the end, the teammate scored and the team cheered together.\n\nWhat is the story's main problem?","choices":["his team was losing and he had not scored","Evan wants to leave the setting before anything happens.","Evan cannot remember anyone's name.","The story has no problem to solve."],"correct":0,"studyAid":{"definition":"The main problem is the central conflict or obstacle a character must deal with, which drives the action of the story.","example":"A character stuck in a storm needs to find shelter; a character loses their favorite toy and must search for it.","strategyClue":"Look for the part of the story that creates tension or a goal the character needs to reach. Ask yourself: 'What is making life difficult for the character right now?'","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: his team was losing and he had not scored. A main problem in a story is the conflict or challenge a character faces. In this story, the pressure Evan feels comes directly from his team being behind and his personal goal to score.","incorrect":["",{"choice":"Evan wants to leave the setting before anything happens.","category":"inaccurate story detail","reason":"The story never mentions Evan wanting to leave; instead, he stays focused on helping his team by passing the ball."},{"choice":"Evan cannot remember anyone's name.","category":"unsupported story detail","reason":"The text does not mention any difficulty with names; this is not a conflict that appears in the story at all."},{"choice":"The story has no problem to solve.","category":"missing conflict identification","reason":"Every story needs a conflict. Without the team losing and the pressure of the game, there would be no reason for Evan to make a difficult decision."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["story elements","character","setting","plot"],"standards":["RL.2-6.3"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-story-elements","sequence":112,"skillIds":[],"standardIds":["RL.2-6.3"]}},{"id":"reading-comprehension-story-elements-q0113","version":3,"contentHash":"sha256:7d6325f26c40d56bd502ae25b24c416f39fb61de6b7554ee3dda30769b580211","question":"Read the story. Grade 4 developing story: Mina was at the hallway before the spelling bee when she felt nervous after hearing older students practice difficult words. Mina felt the pressure of the moment, but she breathed slowly, reviewed her word cards, and remembered how much she had studied. In the end, she walked onto the stage feeling steady.\n\nWhere does the story mainly take place?","choices":["inside a grocery store","the hallway before the spelling bee","on a mountain trail","at a train station"],"correct":1,"studyAid":{"definition":"The setting is the time and place where a story happens. Identifying the setting helps you understand the context of the character's actions.","example":"A story about a space mission is set on a spaceship; a story about a knight is set in a castle.","strategyClue":"Scan the first sentence of the paragraph for location words or phrases that tell you where the main character is located.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: the hallway before the spelling bee. The text explicitly states, 'Mina was at the hallway before the spelling bee,' which confirms this as the specific setting of the story.","incorrect":[{"choice":"inside a grocery store","category":"mismatched setting","reason":"The text mentions a spelling bee and word cards, not groceries or shopping. There is no evidence in the story to suggest a grocery store setting."},"",{"choice":"on a mountain trail","category":"mismatched setting","reason":"The story takes place in a hallway and on a stage, which are indoor settings. A mountain trail is an outdoor environment that does not fit the context of a spelling bee."},{"choice":"at a train station","category":"mismatched setting","reason":"While a train station is a place where people might be nervous, the story focuses on a spelling bee and word cards, which are typically found at schools or event centers, not train stations."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["story elements","character","setting","plot"],"standards":["RL.2-6.3"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-story-elements","sequence":113,"skillIds":[],"standardIds":["RL.2-6.3"]}},{"id":"reading-comprehension-story-elements-q0114","version":3,"contentHash":"sha256:ae7c5d9788f356d9680c1a5555b517430c90567948bf74574190fd5ec77ecfae","question":"Read the story. Grade 4 developing story: Caleb was at the animal shelter when a shy dog hid whenever visitors came near. Caleb felt the pressure of the moment, but Caleb sat quietly nearby each week and let the dog approach when ready. In the end, the dog eventually rested its head beside him.\n\nHow is the problem resolved?","choices":["An adult solves the problem without the character doing anything.","Caleb decides the problem is impossible.","the dog eventually rested its head beside him","The story ends before the problem is addressed."],"correct":2,"studyAid":{"definition":"A resolution is how the main problem or conflict in a story is finally settled or solved by the end of the text.","example":"If a character is lost, the resolution is finding their way home. If a character is hungry, the resolution is getting a meal.","strategyClue":"Look at the very end of the passage and identify the specific action that changes the character's situation or fixes the main challenge they were facing earlier.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: the dog eventually rested its head beside him. The story describes Caleb's patient approach to gain the shy dog's trust, and this action directly shows the dog becoming comfortable and ending the conflict of the dog being shy.","incorrect":[{"choice":"An adult solves the problem without the character doing anything.","category":"misreading character actions","reason":"The story explicitly states that Caleb spent time sitting nearby each week, meaning he was the one actively working to solve the problem, not an adult."},{"choice":"Caleb decides the problem is impossible.","category":"incorrect inference","reason":"Caleb does not give up; instead, he shows patience and persistence, which leads to a successful outcome."},"",{"choice":"The story ends before the problem is addressed.","category":"ignoring story resolution","reason":"The final sentence describes the dog resting its head beside Caleb, which is the clear conclusion and resolution to the dog's shyness."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["story elements","character","setting","plot"],"standards":["RL.2-6.3"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-story-elements","sequence":114,"skillIds":[],"standardIds":["RL.2-6.3"]}},{"id":"reading-comprehension-story-elements-q0115","version":3,"contentHash":"sha256:b91d940be90997178070576ef142d87d7a9cf8827286f09c3753f8237b28c32c","question":"Read the story. Grade 4 developing story: Jada was at a rainy field trip when the outdoor scavenger hunt had to be canceled. Jada felt the pressure of the moment, but she helped classmates create an indoor museum hunt using exhibit clues. In the end, the class discovered details they might have missed.\n\nWhat most likely motivates Jada's actions?","choices":["Jada is trying to avoid helping anyone.","Jada wants to make the problem worse.","Jada hopes nobody notices the problem.","She wanted the trip to stay interesting even after plans changed."],"correct":3,"studyAid":{"definition":"Character motivation is the reason a person in a story acts the way they do. It is often revealed through their actions, choices, and reactions to problems.","example":"A student shares their lunch because they are kind (motivation: kindness); a student studies hard to get an A (motivation: wanting to learn or succeed).","strategyClue":"Look at what the character actually did after the problem started, and ask yourself what 'goal' or 'feeling' would lead someone to behave that way.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: She wanted the trip to stay interesting even after plans changed. Jada's actions—creating a new indoor museum hunt—show she is working to fix the situation and keep her classmates engaged despite the rain canceling their original plans.","incorrect":[{"choice":"Jada is trying to avoid helping anyone.","category":"Contradicts character action","reason":"This is incorrect because the story explicitly states that Jada helped her classmates by creating a new activity, which is the opposite of avoiding others."},{"choice":"Jada wants to make the problem worse.","category":"Negative character motivation","reason":"There is no evidence for this; Jada is being helpful and proactive by finding a solution to the canceled scavenger hunt, not making the situation more difficult."},{"choice":"Jada hopes nobody notices the problem.","category":"Misinterpretation of intent","reason":"Jada is actively engaging with her classmates to create a new hunt, which shows she is addressing the problem openly rather than trying to hide it."},""]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["story elements","character","setting","plot"],"standards":["RL.2-6.3"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-story-elements","sequence":115,"skillIds":[],"standardIds":["RL.2-6.3"]}},{"id":"reading-comprehension-story-elements-q0116","version":3,"contentHash":"sha256:e7feccb21560b7a3e5199cab6923c3539b5192fc40da3102b04b0840ef32afcd","question":"Read the story. Grade 4 developing story: Omar was at the computer lab when his slideshow disappeared when the program froze. Omar felt the pressure of the moment, but he checked the autosave folder and rebuilt two missing slides from his notes. In the end, his presentation was ready before class ended.\n\nWhich word best describes Omar?","choices":["determined","careless","boastful","impatient"],"correct":0,"studyAid":{"definition":"A character trait is a word that describes how a character acts, thinks, or feels based on the actions they take in a story.","example":"If a character shares their lunch, they are 'kind'. If a character waits quietly, they are 'patient'. If a character tries again after failing, they are 'determined'.","strategyClue":"Look at the actions the character takes in the text, then ask yourself: 'What personality quality would make someone act this way?'","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: determined. Omar is determined because he did not give up when his program froze. Instead, he took proactive steps by checking the autosave folder and using his notes to rebuild his work, showing persistence in the face of a challenge.","incorrect":["",{"choice":"careless","category":"character trait error","reason":"Someone who is careless makes sloppy mistakes and does not pay attention. Omar was actually very careful, as he checked his folders and used his notes to fix the problem."},{"choice":"boastful","category":"character trait error","reason":"A boastful person talks too much about their own success to make others jealous. Nothing in the story suggests Omar wanted to brag; he was simply focused on finishing his task."},{"choice":"impatient","category":"character trait error","reason":"An impatient person gives up easily or gets angry when things go wrong. Omar stayed calm and worked methodically to restore his slides, which is the opposite of being impatient."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["story elements","character","setting","plot"],"standards":["RL.2-6.3"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-story-elements","sequence":116,"skillIds":[],"standardIds":["RL.2-6.3"]}},{"id":"reading-comprehension-story-elements-q0117","version":3,"contentHash":"sha256:96f5fa9f9a09c42720aae4b4766fcbf01d4a77234dd358bb5ed0ff6807e14654","question":"Read the story. Grade 4 developing story: Nora was at the neighborhood sidewalk when an elderly neighbor struggled to carry groceries up the steps. Nora felt the pressure of the moment, but Nora asked permission, carried two light bags, and held the gate open. In the end, the neighbor thanked her and invited her to pick tomatoes later.\n\nWhat is the story's main problem?","choices":["Nora wants to leave the setting before anything happens.","an elderly neighbor struggled to carry groceries up the steps","Nora cannot remember anyone's name.","The story has no problem to solve."],"correct":1,"studyAid":{"definition":"The main problem of a story is the central conflict or challenge that a character encounters, which usually triggers the actions they take later.","example":"In a fairy tale, the main problem might be a dragon blocking a bridge; in a school story, it might be a student struggling to finish a difficult project.","strategyClue":"Look for a sentence that describes a character facing a challenge, a barrier, or a situation that requires help or a change in plans.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: an elderly neighbor struggled to carry groceries up the steps. A main problem in a story is the conflict or challenge that a character faces, which prompts them to take action. This struggle is the situation that Nora observes and decides to help with.","incorrect":[{"choice":"Nora wants to leave the setting before anything happens.","category":"misreading text","reason":"This is incorrect because the story describes Nora engaging with her neighbor rather than trying to leave or avoid the situation."},"",{"choice":"Nora cannot remember anyone's name.","category":"unsupported detail","reason":"This detail is not mentioned in the text. A problem must be based on the information provided in the story."},{"choice":"The story has no problem to solve.","category":"ignoring story conflict","reason":"Stories usually center on a character facing a challenge. In this story, the neighbor's difficulty with the groceries creates a clear challenge that Nora addresses."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["story elements","character","setting","plot"],"standards":["RL.2-6.3"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-story-elements","sequence":117,"skillIds":[],"standardIds":["RL.2-6.3"]}},{"id":"reading-comprehension-story-elements-q0118","version":3,"contentHash":"sha256:100ca180cf9b5d085b3b5932e178eb91a0b085652937f2c5afc7d1456d1340e2","question":"Read the story. Grade 4 developing story: Ben was at the chess club table when he lost three games in a row. Ben felt the pressure of the moment, but he asked his opponent to show the move that trapped his queen. In the end, he used the lesson to avoid the trap in the next game.\n\nWhere does the story mainly take place?","choices":["on a mountain trail","inside a grocery store","the chess club table","at a train station"],"correct":2,"studyAid":{"definition":"The setting is the place or time where a story happens. Good readers look for specific nouns that name a location.","example":"If the story mentions 'books' and 'shelves,' the setting is likely a library. If it mentions 'swimming' and 'sand,' the setting is a beach.","strategyClue":"Scan the first sentence of the story for a prepositional phrase that describes a location. Match that specific location to the choices provided.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: the chess club table. The story explicitly states, 'Ben was at the chess club table,' which identifies the specific location where the events take place.","incorrect":[{"choice":"on a mountain trail","category":"setting mismatch","reason":"There is no mention of hiking or trails in the story. The characters are focused on a game of chess, not an outdoor trek."},{"choice":"inside a grocery store","category":"setting mismatch","reason":"The story mentions a chess board and players, not food items or aisles. A grocery store does not fit the context of a chess match."},"",{"choice":"at a train station","category":"setting mismatch","reason":"The story does not describe trains, platforms, or travel. The action is entirely contained within the activity of playing chess at a table."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["story elements","character","setting","plot"],"standards":["RL.2-6.3"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-story-elements","sequence":118,"skillIds":[],"standardIds":["RL.2-6.3"]}},{"id":"reading-comprehension-story-elements-q0119","version":3,"contentHash":"sha256:2f985f1575a580c4f3acd445d490148d797d1a5aa3edb493ce00b1eeb9221d8e","question":"Read the story. Grade 4 developing story: Talia was at the school hallway after dismissal when she found a wallet with lunch money and a student ID. Talia felt the pressure of the moment, but she took it to the office before leaving for practice. In the end, the owner got the wallet back before the buses left.\n\nHow is the problem resolved?","choices":["The story ends before the problem is addressed.","Talia decides the problem is impossible.","An adult solves the problem without the character doing anything.","the owner got the wallet back before the buses left"],"correct":3,"studyAid":{"definition":"The resolution of a story is the final part of the plot where the main character's problem is solved or the conflict comes to an end.","example":"A lost dog is found and returned to its owner; a student finishes their project and gets a good grade.","strategyClue":"Look for transition words like 'In the end' or 'Finally' at the very conclusion of the story to identify the specific moment the conflict was settled.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: the owner got the wallet back before the buses left. The story explicitly states that the resolution occurred when the owner retrieved their property before the school transportation departed.","incorrect":[{"choice":"The story ends before the problem is addressed.","category":"misreading plot points","reason":"The text clearly states the resolution occurred 'In the end,' meaning the problem was successfully addressed by Talia taking it to the office."},{"choice":"Talia decides the problem is impossible.","category":"character motivation error","reason":"Talia did not give up; she took positive action by bringing the found item to the school office, directly solving the problem."},{"choice":"An adult solves the problem without the character doing anything.","category":"misinterpreting character actions","reason":"Talia is the one who found the wallet and initiated the resolution by taking it to the office; she played an active role in solving the problem."},""]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["story elements","character","setting","plot"],"standards":["RL.2-6.3"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-story-elements","sequence":119,"skillIds":[],"standardIds":["RL.2-6.3"]}},{"id":"reading-comprehension-story-elements-q0120","version":4,"contentHash":"sha256:4280543f9b52d6b1d3db93200c4657bbe9e370f500de23cee19f531bbcf022b6","question":"Read the story. Grade 4 developing story: Diego was at the creek behind the park when he saw that stepping stones had shifted after heavy rain. Diego felt the pressure of the moment, but he warned younger children to use the bridge and told a ranger. In the end, the crossing was closed until it could be repaired.\n\nWhat most likely motivates Diego's actions?","choices":["He wanted others to stay safe.","Diego wants to make the problem worse.","Diego hopes nobody notices the problem.","Diego is trying to avoid helping anyone."],"correct":0,"studyAid":{"definition":"A character's motivation is the reason why they do what they do, often revealed by their actions, feelings, and the choices they make in a story.","example":"If a character shares their lunch, they might be motivated by kindness; if they study hard for a test, they might be motivated by a desire to learn or succeed.","strategyClue":"Look at the specific actions the character takes in the story and ask yourself what the end result of those actions is. If the actions prevent harm or solve a problem, the character's motivation is likely rooted in care or responsibility.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: He wanted others to stay safe. Diego's actions—warning the younger children to use the bridge and reporting the issue to a ranger—directly demonstrate his concern for the safety of others.","incorrect":["",{"choice":"Diego wants to make the problem worse.","category":"misinterpreting character motive","reason":"This is incorrect because Diego's actions are helpful and constructive, not destructive. He tries to solve the problem by notifying an adult and warning others."},{"choice":"Diego hopes nobody notices the problem.","category":"ignoring text evidence","reason":"This choice contradicts the text, which states that Diego actively warned others and reported the issue to a ranger, meaning he wanted the problem to be addressed."},{"choice":"Diego is trying to avoid helping anyone.","category":"misinterpreting character actions","reason":"This is incorrect because warning children and telling a ranger are proactive ways of helping people avoid danger, rather than avoiding responsibility."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["story elements","character","setting","plot"],"standards":["RL.2-6.3"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":70,"reviewPriority":"high","sourceSet":"reading-comprehension-story-elements","sequence":120,"skillIds":[],"standardIds":["RL.2-6.3"]}},{"id":"reading-comprehension-story-elements-q0121","version":3,"contentHash":"sha256:cfd67fb04c9b7f12f298a4390104dd5e7bd5cec2f664874cf086d51f286424d3","question":"Read the story. Grade 4 challenge story: Lena was at the classroom supply table when her group's poster tore right before the science fair. At first, the situation seemed discouraging. Instead of reacting too quickly, Lena thought about what mattered most: she wanted her group to feel ready instead of giving up. Then she calmly taped the back, asked for a spare sheet, and divided the repair jobs. In the end, the group finished on time.\n\nWhich word best describes Lena?","choices":["careless","resourceful","boastful","impatient"],"correct":1,"studyAid":{"definition":"To infer a character trait, look for evidence in the text by matching a person's actions with descriptive personality adjectives.","example":"If a character shares their toys, they are 'generous.' If a character waits their turn without complaining, they are 'patient.'","strategyClue":"List the actions the character takes in the story, then ask yourself what kind of person would choose to do those specific things in a stressful situation.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: resourceful. Lena showed she was resourceful because she solved a difficult problem calmly and efficiently by taping the poster, asking for help, and dividing the tasks.","incorrect":[{"choice":"careless","category":"opposite character trait","reason":"Careless people make mistakes because they aren't paying attention. Lena was the opposite; she acted thoughtfully and carefully to fix the poster."},"",{"choice":"boastful","category":"unsupported character trait","reason":"A boastful person brags about themselves. Lena was focused on helping her group, not showing off or talking about how great she is."},{"choice":"impatient","category":"opposite character trait","reason":"Impatient people react quickly and get frustrated. The story says Lena chose not to react too quickly and stayed calm instead."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["story elements","character","setting","plot"],"standards":["RL.2-6.3"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-story-elements","sequence":121,"skillIds":[],"standardIds":["RL.2-6.3"]}},{"id":"reading-comprehension-story-elements-q0122","version":3,"contentHash":"sha256:13ee443fa703e48311499b186a161d3457513fdbf31247fae47b9474139b40ea","question":"Read the story. Grade 4 challenge story: Mateo was at the school bus line when a younger student dropped a folder and papers scattered. At first, the situation seemed discouraging. Instead of reacting too quickly, Mateo thought about what mattered most: he noticed someone needed help more than he needed to keep his place. Then Mateo stepped out of line, gathered the papers, and helped sort them by subject. In the end, the younger student smiled and found the missing homework.\n\nWhat is the story's main problem?","choices":["Mateo cannot remember anyone's name.","Mateo wants to leave the setting before anything happens.","a younger student dropped a folder and papers scattered","The story has no problem to solve."],"correct":2,"studyAid":{"definition":"The main problem of a story is the struggle or challenge the main character faces that gets the action moving.","example":"A lost puppy in the woods, a difficult homework assignment, a rainy day cancelling a soccer game.","strategyClue":"Look for the sentence that describes a sudden change or a negative event that requires someone to make a choice or take action.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: a younger student dropped a folder and papers scattered. The main problem is the conflict or obstacle that starts the action in a story. When the papers fall, it creates an immediate situation that Mateo must choose how to address.","incorrect":[{"choice":"Mateo cannot remember anyone's name.","category":"not in text","reason":"The story does not mention Mateo trying to remember names or having trouble with them; this detail is not supported by the narrative."},{"choice":"Mateo wants to leave the setting before anything happens.","category":"contrary to evidence","reason":"This is incorrect because Mateo actually chooses to step out of line to help rather than trying to leave or ignore the situation."},"",{"choice":"The story has no problem to solve.","category":"missing conflict","reason":"Every story needs an inciting event or a complication. The mess of scattered papers provides a clear challenge for the character to fix."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["story elements","character","setting","plot"],"standards":["RL.2-6.3"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-story-elements","sequence":122,"skillIds":[],"standardIds":["RL.2-6.3"]}},{"id":"reading-comprehension-story-elements-q0123","version":3,"contentHash":"sha256:4887dfbc01cf5ea92f73b79127ec309906059d056ca9bd267c65979b53340ce5","question":"Read the story. Grade 4 challenge story: Priya was at the community garden when her bean plants wilted after several hot days. At first, the situation seemed discouraging. Instead of reacting too quickly, Priya thought about what mattered most: she wanted to understand what the plants needed before trying a solution. Then she checked the soil, moved mulch around the stems, and changed the watering schedule. In the end, new green leaves appeared the next week.\n\nWhere does the story mainly take place?","choices":["at a train station","inside a grocery store","on a mountain trail","the community garden"],"correct":3,"studyAid":{"definition":"The setting of a story is the time and place where the characters' actions and events occur.","example":"A story about astronauts happens in space; a story about a baker happens in a kitchen.","strategyClue":"Scan the first two sentences for nouns that describe a physical place or location, then double-check if the actions in the story match that environment.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: the community garden. The text explicitly states, 'Priya was at the community garden,' identifying this as the specific setting for the narrative events.","incorrect":[{"choice":"at a train station","category":"incorrect location","reason":"The story never mentions trains or a station. The text focuses on soil, mulch, and bean plants, which are features of a garden, not a transportation hub."},{"choice":"inside a grocery store","category":"incorrect location","reason":"While grocery stores sell plants, the story describes growing and caring for living plants in soil, which happens in a garden, not inside a retail shop."},{"choice":"on a mountain trail","category":"incorrect location","reason":"There is no mention of hiking, elevation, or paths in the mountains. The activities described, such as watering and mulching, indicate a managed garden space."},""]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["story elements","character","setting","plot"],"standards":["RL.2-6.3"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-story-elements","sequence":123,"skillIds":[],"standardIds":["RL.2-6.3"]}},{"id":"reading-comprehension-story-elements-q0124","version":3,"contentHash":"sha256:f214de5d7be5e455cc154d05b3d3ba73d1fb3e2029a302ebe5ff294b5cf7aeda","question":"Read the story. Grade 4 challenge story: Noah was at the music room when he kept missing the same measure during recorder practice. At first, the situation seemed discouraging. Instead of reacting too quickly, Noah thought about what mattered most: he wanted to improve even after the mistake felt frustrating. Then he slowed the song down, clapped the rhythm, and practiced four notes at a time. In the end, he played the measure correctly during rehearsal.\n\nHow is the problem resolved?","choices":["he played the measure correctly during rehearsal","Noah decides the problem is impossible.","An adult solves the problem without the character doing anything.","The story ends before the problem is addressed."],"correct":0,"studyAid":{"definition":"A resolution is how a character solves a problem or how a story's conflict reaches its end.","example":"Problem: A lost key. Resolution: Searching under the couch and finding it. Problem: Not knowing a math answer. Resolution: Reviewing the textbook to find the solution.","strategyClue":"Look at the very last sentence or the final action of the main character; the resolution is almost always found in the conclusion of the narrative.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: he played the measure correctly during rehearsal. The text explicitly states the resolution in the final sentence when Noah successfully performs the difficult part of the song after practicing.","incorrect":["",{"choice":"Noah decides the problem is impossible.","category":"misreading character motivation","reason":"The text explains that Noah practiced by clapping the rhythm and slowing the song down, showing that he believed improvement was possible, not impossible."},{"choice":"An adult solves the problem without the character doing anything.","category":"incorrect plot summary","reason":"The story highlights Noah's personal effort—clapping the rhythm and playing notes in small chunks—rather than an adult stepping in to fix it for him."},{"choice":"The story ends before the problem is addressed.","category":"ignoring story structure","reason":"The story provides a clear conclusion where Noah overcomes the frustration of missing the measure by successfully playing it at the end."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["story elements","character","setting","plot"],"standards":["RL.2-6.3"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-story-elements","sequence":124,"skillIds":[],"standardIds":["RL.2-6.3"]}},{"id":"reading-comprehension-story-elements-q0125","version":3,"contentHash":"sha256:a64e87cad75d2abe4e53a6e80d138ae68b3ce2dabeb45fbd767c8e33e9348d6f","question":"Read the story. Grade 4 challenge story: Ari was at the lunch table when two friends argued about who should choose the game at recess. At first, the situation seemed discouraging. Instead of reacting too quickly, Ari thought about what mattered most: ari wanted both friends to feel heard. Then Ari suggested each friend pick one round and then vote on a final round. In the end, both friends agreed and the argument ended.\n\nWhat most likely motivates Ari's actions?","choices":["Ari wants to make the problem worse.","Ari wanted both friends to feel heard.","Ari hopes nobody notices the problem.","Ari is trying to avoid helping anyone."],"correct":1,"studyAid":{"definition":"Character motivation is the reason a character says or does something, often found by looking for clues in the text that explain their thoughts or goals.","example":"If a character shares their lunch, their motivation might be kindness. If they study hard, their motivation might be wanting to get an A.","strategyClue":"Look for sentences in the story that start with 'because' or describe what the character thinks is important; these clues reveal the 'why' behind their actions.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: Ari wanted both friends to feel heard. The text explicitly states, 'Ari thought about what mattered most: ari wanted both friends to feel heard,' which explains the reasoning behind Ari's suggested compromise.","incorrect":[{"choice":"Ari wants to make the problem worse.","category":"misinterpreted character motivation","reason":"Ari's actions, such as suggesting a fair compromise, show a desire to solve the conflict, not to intensify or worsen it."},"",{"choice":"Ari hopes nobody notices the problem.","category":"misinterpreted character intent","reason":"Ari chooses to actively participate in the conversation to resolve the issue rather than ignoring it or hoping it goes unnoticed."},{"choice":"Ari is trying to avoid helping anyone.","category":"misinterpreted character actions","reason":"By proposing a way for both friends to take turns and vote, Ari is directly helping both friends reach an agreement."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["story elements","character","setting","plot"],"standards":["RL.2-6.3"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-story-elements","sequence":125,"skillIds":[],"standardIds":["RL.2-6.3"]}},{"id":"reading-comprehension-story-elements-q0126","version":3,"contentHash":"sha256:f83a77f7d423dd873085be85ce735e394c3128cd6f99013e97f7a665ee11f06e","question":"Read the story. Grade 4 challenge story: Sofia was at the school art show when she worried that her painting looked different from everyone else's. At first, the situation seemed discouraging. Instead of reacting too quickly, Sofia thought about what mattered most: she wanted her work to show what she imagined. Then she listened as visitors asked about her unusual colors and bold shapes. In the end, she began to feel proud of her own style.\n\nWhich word best describes Sofia?","choices":["boastful","careless","creative","impatient"],"correct":2,"studyAid":{"definition":"A character trait is a word that describes a person's personality or behavior based on what they say, think, or do in a story.","example":"A character who helps others might be 'kind.' A character who waits their turn might be 'patient.'","strategyClue":"Look at the actions and thoughts of the character in the text. Ask yourself, 'What do these specific actions tell me about how the person thinks or feels?'","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: creative. Sofia shows her creativity by using unusual colors and bold shapes, and by focusing on expressing her own imagination rather than copying others.","incorrect":[{"choice":"boastful","category":"character trait error","reason":"Being boastful means bragging about oneself. Sofia actually feels worried at first and simply wants to share her own vision, so this does not fit her behavior."},{"choice":"careless","category":"character trait error","reason":"Careless means not paying attention to detail. Sofia put thought into her painting and reacted to visitors' questions, showing she is thoughtful, not careless."},"",{"choice":"impatient","category":"character trait error","reason":"Impatient means wanting things to happen right away. The story says Sofia chose not to react 'too quickly,' which shows she is patient and reflective."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["story elements","character","setting","plot"],"standards":["RL.2-6.3"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-story-elements","sequence":126,"skillIds":[],"standardIds":["RL.2-6.3"]}},{"id":"reading-comprehension-story-elements-q0127","version":3,"contentHash":"sha256:97456f222ae973fc01f9082bbbf4cfe1a0479951f24882e8e34db928fcc9e2f8","question":"Read the story. Grade 4 challenge story: Evan was at the soccer field when his team was losing and he had not scored. At first, the situation seemed discouraging. Instead of reacting too quickly, Evan thought about what mattered most: he cared more about helping the team than being the scorer. Then he passed to a teammate who had a clear shot instead of kicking from a bad angle. In the end, the teammate scored and the team cheered together.\n\nWhat is the story's main problem?","choices":["The story has no problem to solve.","Evan wants to leave the setting before anything happens.","Evan cannot remember anyone's name.","his team was losing and he had not scored"],"correct":3,"studyAid":{"definition":"The main problem (or conflict) is the struggle the main character faces. It is usually introduced early in the story and is what the characters try to fix.","example":"A lost puppy looking for home, a baker who ran out of flour for a cake, a student who forgot their homework on a test day.","strategyClue":"Look at the very beginning of the passage and ask yourself, 'What is bothering the main character right now?' or 'What is the goal they are trying to reach?'","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: his team was losing and he had not scored. The main problem is the challenge or obstacle the character faces at the beginning of the story that drives the action.","incorrect":[{"choice":"The story has no problem to solve.","category":"misidentified plot structure","reason":"Every story needs a conflict or problem to keep the reader interested. In this story, the score and the game status created an obstacle for Evan."},{"choice":"Evan wants to leave the setting before anything happens.","category":"unsupported story detail","reason":"The text shows Evan staying to play, think, and help his team. There is no evidence in the story that Evan wanted to leave."},{"choice":"Evan cannot remember anyone's name.","category":"fictional story detail","reason":"This information is not mentioned in the story. You must look for the challenge Evan faces regarding the soccer game itself."},""]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["story elements","character","setting","plot"],"standards":["RL.2-6.3"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-story-elements","sequence":127,"skillIds":[],"standardIds":["RL.2-6.3"]}},{"id":"reading-comprehension-story-elements-q0128","version":3,"contentHash":"sha256:657af486977db648512b5d790a92094213c9aa254f4b327a0cf17b02b0ed8b8e","question":"Read the story. Grade 4 challenge story: Mina was at the hallway before the spelling bee when she felt nervous after hearing older students practice difficult words. At first, the situation seemed discouraging. Instead of reacting too quickly, Mina thought about what mattered most: she wanted to manage her nerves so she could do her best. Then she breathed slowly, reviewed her word cards, and remembered how much she had studied. In the end, she walked onto the stage feeling steady.\n\nWhere does the story mainly take place?","choices":["the hallway before the spelling bee","inside a grocery store","on a mountain trail","at a train station"],"correct":0,"studyAid":{"definition":"The setting is the time and place where a story happens. Writers provide clues through specific nouns and events to show the reader where the character is located.","example":"A story about basketball might be set in a gym; a story about a campfire might be set in the woods.","strategyClue":"Scan the first paragraph for location words or nouns that describe a place, and compare them against the options provided to see which one is mentioned in the text.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: the hallway before the spelling bee. The text explicitly states, 'Mina was at the hallway before the spelling bee,' providing the specific setting for the story's events.","incorrect":["",{"choice":"inside a grocery store","category":"incorrect story setting","reason":"The story never mentions food, aisles, or shopping. Always look for specific nouns in the text like 'hallway' or 'stage' to identify the setting."},{"choice":"on a mountain trail","category":"incorrect story setting","reason":"There are no mentions of hiking, trees, or mountains. This setting does not match the actions of reviewing word cards or walking onto a stage."},{"choice":"at a train station","category":"incorrect story setting","reason":"The story describes a spelling bee and a stage. A train station would involve trains, platforms, or travel, which are not present in this text."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["story elements","character","setting","plot"],"standards":["RL.2-6.3"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-story-elements","sequence":128,"skillIds":[],"standardIds":["RL.2-6.3"]}},{"id":"reading-comprehension-story-elements-q0129","version":3,"contentHash":"sha256:56cfc7c3ef1b6567a3cbaf60e434403d4f07a44d048079a790ce944ba599edb5","question":"Read the story. Grade 4 challenge story: Caleb was at the animal shelter when a shy dog hid whenever visitors came near. At first, the situation seemed discouraging. Instead of reacting too quickly, Caleb thought about what mattered most: he wanted the dog to feel safe, not rushed. Then Caleb sat quietly nearby each week and let the dog approach when ready. In the end, the dog eventually rested its head beside him.\n\nHow is the problem resolved?","choices":["Caleb decides the problem is impossible.","the dog eventually rested its head beside him","An adult solves the problem without the character doing anything.","The story ends before the problem is addressed."],"correct":1,"studyAid":{"definition":"A resolution is how a problem or conflict in a story is settled or fixed by the end of the narrative.","example":"A lost kitten is found by its owner (problem: lost; resolution: found); A broken vase is glued back together (problem: broken; resolution: repaired).","strategyClue":"Look at the final sentence of the paragraph and ask yourself what has changed for the main character or the dog compared to how the story began.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: the dog eventually rested its head beside him. This choice describes the specific moment the dog felt safe enough to approach Caleb, which signals that the initial problem of the dog being shy and fearful has been overcome.","incorrect":[{"choice":"Caleb decides the problem is impossible.","category":"misreading story events","reason":"This is incorrect because Caleb does not give up; instead, he shows patience by sitting quietly each week to earn the dog's trust."},"",{"choice":"An adult solves the problem without the character doing anything.","category":"inaccurate summary","reason":"The story explicitly shows Caleb taking action by sitting nearby and waiting for the dog to be ready, rather than relying on someone else to fix it."},{"choice":"The story ends before the problem is addressed.","category":"ignoring final resolution","reason":"The final sentence describes the dog resting its head beside Caleb, which directly shows that the dog is no longer hiding and the problem is resolved."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["story elements","character","setting","plot"],"standards":["RL.2-6.3"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-story-elements","sequence":129,"skillIds":[],"standardIds":["RL.2-6.3"]}},{"id":"reading-comprehension-story-elements-q0130","version":3,"contentHash":"sha256:c26ca43b5ec0cf0238254f3741c8bd2479c913fd9ab75646529f778effa9e4fb","question":"Read the story. Grade 4 challenge story: Jada was at a rainy field trip when the outdoor scavenger hunt had to be canceled. At first, the situation seemed discouraging. Instead of reacting too quickly, Jada thought about what mattered most: she wanted the trip to stay interesting even after plans changed. Then she helped classmates create an indoor museum hunt using exhibit clues. In the end, the class discovered details they might have missed.\n\nWhat most likely motivates Jada's actions?","choices":["Jada hopes nobody notices the problem.","Jada wants to make the problem worse.","She wanted the trip to stay interesting even after plans changed.","Jada is trying to avoid helping anyone."],"correct":2,"studyAid":{"definition":"Character motivation is the reason why a person in a story says or does specific things. It is often revealed through the character's thoughts and the actions they take to solve a problem.","example":"If a character is hungry, they might bake a snack. If a character is lonely, they might invite a friend to play.","strategyClue":"Look for sentences that describe the character's internal thoughts or the goals they are working toward after a challenge appears in the story.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: She wanted the trip to stay interesting even after plans changed. The story explicitly states that Jada thought about what mattered most: keeping the trip interesting despite the canceled outdoor plans, which prompted her to organize the indoor museum hunt.","incorrect":[{"choice":"Jada hopes nobody notices the problem.","category":"incorrect character motivation","reason":"The story shows Jada taking active steps to solve a problem for her class, rather than trying to hide the fact that the scavenger hunt was canceled."},{"choice":"Jada wants to make the problem worse.","category":"opposite character intention","reason":"Jada's actions, such as creating an indoor museum hunt, are helpful and constructive, not destructive or intended to make things more difficult."},"",{"choice":"Jada is trying to avoid helping anyone.","category":"contrary evidence","reason":"This is incorrect because Jada directly helps her classmates by working with them to create a new activity when the original plan failed."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["story elements","character","setting","plot"],"standards":["RL.2-6.3"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-story-elements","sequence":130,"skillIds":[],"standardIds":["RL.2-6.3"]}},{"id":"reading-comprehension-story-elements-q0131","version":3,"contentHash":"sha256:3d05c40a78e69d798d7e0c5d3f5d5a8b3a3e9200b6b526f201d61c8b02f65bc4","question":"Read the story. Grade 4 challenge story: Omar was at the computer lab when his slideshow disappeared when the program froze. At first, the situation seemed discouraging. Instead of reacting too quickly, Omar thought about what mattered most: he wanted to recover his work instead of quitting. Then he checked the autosave folder and rebuilt two missing slides from his notes. In the end, his presentation was ready before class ended.\n\nWhich word best describes Omar?","choices":["impatient","careless","boastful","determined"],"correct":3,"studyAid":{"definition":"Character traits are qualities that define how a person thinks, acts, or feels, often revealed by the choices they make during a conflict.","example":"If a character shares their toys, they are generous. If a character hides when it is time to do chores, they might be lazy.","strategyClue":"Look for the specific actions the character takes when they face a problem. Ask yourself: 'What does this action tell me about the kind of person they are?'","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: determined. Omar shows determination because he stays focused on his goal to recover his work, rebuilds his missing slides from notes, and finishes before class, showing persistence instead of giving up.","incorrect":[{"choice":"impatient","category":"character trait error","reason":"An impatient person would have acted too quickly or quit. Omar specifically chooses not to react too quickly, which is the opposite of being impatient."},{"choice":"careless","category":"character trait error","reason":"A careless person would not take the time to check the autosave folder or use his notes to carefully rebuild the missing work."},{"choice":"boastful","category":"character trait error","reason":"Being boastful means bragging about oneself. Nothing in the story shows Omar talking about his skills or trying to get attention from others."},""]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["story elements","character","setting","plot"],"standards":["RL.2-6.3"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-story-elements","sequence":131,"skillIds":[],"standardIds":["RL.2-6.3"]}},{"id":"reading-comprehension-story-elements-q0132","version":3,"contentHash":"sha256:d89d202899f9dbb2b0bbe5b124e4ecb8b6da4b382dcd4476763c001d2cc5cdf9","question":"Read the story. Grade 4 challenge story: Nora was at the neighborhood sidewalk when an elderly neighbor struggled to carry groceries up the steps. At first, the situation seemed discouraging. Instead of reacting too quickly, Nora thought about what mattered most: she saw a way to make someone's task easier. Then Nora asked permission, carried two light bags, and held the gate open. In the end, the neighbor thanked her and invited her to pick tomatoes later.\n\nWhat is the story's main problem?","choices":["an elderly neighbor struggled to carry groceries up the steps","Nora wants to leave the setting before anything happens.","Nora cannot remember anyone's name.","The story has no problem to solve."],"correct":0,"studyAid":{"definition":"The main problem or conflict in a story is the challenge, obstacle, or difficulty that the main character must face or overcome.","example":"A cat stuck in a tree, a student losing their homework, or a character trying to win a difficult race.","strategyClue":"Look for the sentence that describes a character facing a difficulty or an unwanted situation, then ask yourself, 'What does the main character need to fix or change here?'","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: an elderly neighbor struggled to carry groceries up the steps. A main problem, or conflict, is the situation that needs to be solved. Nora's goal is to help the neighbor overcome this struggle.","incorrect":["",{"choice":"Nora wants to leave the setting before anything happens.","category":"not supported by text","reason":"This does not happen in the story. In fact, Nora chooses to stay and help the neighbor rather than leave."},{"choice":"Nora cannot remember anyone's name.","category":"not supported by text","reason":"The story never mentions Nora having trouble remembering names; her focus is entirely on helping with the groceries."},{"choice":"The story has no problem to solve.","category":"misidentifying plot structure","reason":"Most stories have a central conflict. Here, the struggle to carry groceries creates a need for assistance, which is the problem Nora solves."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["story elements","character","setting","plot"],"standards":["RL.2-6.3"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-story-elements","sequence":132,"skillIds":[],"standardIds":["RL.2-6.3"]}},{"id":"reading-comprehension-story-elements-q0133","version":3,"contentHash":"sha256:ee726bf61c1f237595b30110d130746f8aba0df6f02add446aea80dce6ff5bec","question":"Read the story. Grade 4 challenge story: Ben was at the chess club table when he lost three games in a row. At first, the situation seemed discouraging. Instead of reacting too quickly, Ben thought about what mattered most: he wanted to learn from mistakes instead of hiding them. Then he asked his opponent to show the move that trapped his queen. In the end, he used the lesson to avoid the trap in the next game.\n\nWhere does the story mainly take place?","choices":["inside a grocery store","the chess club table","on a mountain trail","at a train station"],"correct":1,"studyAid":{"definition":"The setting is the time and place where a story happens. Finding the setting involves looking for clues about where the characters are located.","example":"If the story says 'The waves crashed against the sand,' the setting is the beach. If the story mentions 'The bell rang in the classroom,' the setting is a school.","strategyClue":"Scan the first two sentences for nouns that describe a location. Highlight any phrases that tell you where the character is standing or sitting.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: the chess club table. The text explicitly states, 'Ben was at the chess club table' at the beginning of the story, establishing the setting.","incorrect":[{"choice":"inside a grocery store","category":"incorrect location setting","reason":"There is no mention of food, shopping, or a store in the text. The characters are focused on playing chess, not buying groceries."},"",{"choice":"on a mountain trail","category":"incorrect location setting","reason":"The text describes Ben playing games and talking to an opponent. A mountain trail is an outdoor setting, which does not fit the context of a chess match."},{"choice":"at a train station","category":"incorrect location setting","reason":"While a train station is a place where people sit, the story focuses entirely on chess moves and traps, which confirms the chess club as the specific location."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["story elements","character","setting","plot"],"standards":["RL.2-6.3"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-story-elements","sequence":133,"skillIds":[],"standardIds":["RL.2-6.3"]}},{"id":"reading-comprehension-story-elements-q0134","version":3,"contentHash":"sha256:778c6f366de24cd556cb846f9680a1f1b68d0f69ea8a99124bde5bb729ac4768","question":"Read the story. Grade 4 challenge story: Talia was at the school hallway after dismissal when she found a wallet with lunch money and a student ID. At first, the situation seemed discouraging. Instead of reacting too quickly, Talia thought about what mattered most: she knew the wallet belonged to someone else. Then she took it to the office before leaving for practice. In the end, the owner got the wallet back before the buses left.\n\nHow is the problem resolved?","choices":["An adult solves the problem without the character doing anything.","Talia decides the problem is impossible.","the owner got the wallet back before the buses left","The story ends before the problem is addressed."],"correct":2,"studyAid":{"definition":"A story's resolution is how the conflict or problem mentioned in the text is settled or fixed by the end.","example":"Problem: A lost key. Resolution: Someone found the key and opened the door.","strategyClue":"Look at the very last sentence of the passage to find the outcome of the situation, then match that outcome to the provided choices.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: the owner got the wallet back before the buses left. This is the direct result of Talia taking the found item to the school office, which allows the owner to be identified and receive their property.","incorrect":[{"choice":"An adult solves the problem without the character doing anything.","category":"misreading character actions","reason":"The story explicitly states that Talia took the initiative to bring the wallet to the office. She played a key role in the resolution."},{"choice":"Talia decides the problem is impossible.","category":"misunderstanding character choices","reason":"Talia does not give up; she pauses to think about what matters most and then takes helpful action to return the items."},"",{"choice":"The story ends before the problem is addressed.","category":"ignoring story conclusion","reason":"The final sentence provides a clear outcome, explaining that the owner successfully retrieved the wallet before the buses departed."}]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["story elements","character","setting","plot"],"standards":["RL.2-6.3"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-story-elements","sequence":134,"skillIds":[],"standardIds":["RL.2-6.3"]}},{"id":"reading-comprehension-story-elements-q0135","version":4,"contentHash":"sha256:dddcec9a0bcbab50f60ce1b1b5e4a76e6c2bc27da6733650fad98865123fb4a4","question":"Read the story. Grade 4 challenge story: Diego was at the creek behind the park when he saw that stepping stones had shifted after heavy rain. At first, the situation seemed discouraging. Instead of reacting too quickly, Diego thought about what mattered most: he wanted others to stay safe. Then he warned younger children to use the bridge and told a ranger. In the end, the crossing was closed until it could be repaired.\n\nWhat most likely motivates Diego's actions?","choices":["Diego is trying to avoid helping anyone.","Diego wants to make the problem worse.","Diego hopes nobody notices the problem.","He wanted others to stay safe."],"correct":3,"studyAid":{"definition":"Motivation is the 'why' behind a character's actions; it is the reason they choose to do what they do in a story.","example":"A student studies hard because they want to learn (motivation), not just because they like books.","strategyClue":"Look for sentences in the text that explain the character's thoughts or feelings immediately before or after they take a major action.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: He wanted others to stay safe. The text explicitly states Diego's motivation when it says, 'he wanted others to stay safe' after he noticed the dangerous stepping stones.","incorrect":[{"choice":"Diego is trying to avoid helping anyone.","category":"contradicts text evidence","reason":"This is incorrect because the story describes Diego taking active steps to help by warning children and informing a park ranger."},{"choice":"Diego wants to make the problem worse.","category":"opposite of motive","reason":"This is incorrect because Diego's actions, such as warning others to use the bridge, show he is trying to fix the problem and prevent accidents."},{"choice":"Diego hopes nobody notices the problem.","category":"ignores character actions","reason":"This is incorrect because Diego intentionally brings attention to the hazard by telling a ranger, showing he wants the situation to be addressed."},""]},"metadata":{"gradeLevels":[5],"difficultyByGrade":{"5":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"analyze-and-explain","languageDemand":"extended-context","skills":["story elements","character","setting","plot"],"standards":["RL.2-6.3"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":90,"reviewPriority":"high","sourceSet":"reading-comprehension-story-elements","sequence":135,"skillIds":[],"standardIds":["RL.2-6.3"]}},{"id":"reading-comprehension-story-elements-q0136","version":3,"contentHash":"sha256:dc90dabb6619d7820949378b60f4242a681dab7f1a9367d330569102c6e10ec0","question":"Read the story. Grade 5 foundation story: Lena was at the classroom supply table when her group's poster tore right before the science fair. Lena she calmly taped the back, asked for a spare sheet, and divided the repair jobs. In the end, the group finished on time.\n\nWhich word best describes Lena?","choices":["resourceful","careless","boastful","impatient"],"correct":0,"studyAid":{"definition":"A character trait describes a person's personality or behavior. To find it, look at what the character says, does, and how they react to challenges.","example":"A character who shares their toys is 'generous'. A character who creates a new plan when one fails is 'resourceful'.","strategyClue":"List the actions Lena takes in the story, then think of a single word that describes someone who acts that way when facing a difficult situation.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: resourceful. Lena shows this trait because she quickly finds a solution (taping the back), asks for extra materials, and organizes her group to fix the problem efficiently.","incorrect":["",{"choice":"careless","category":"incorrect trait","reason":"Careless people make messy mistakes. Lena is the opposite because she acts carefully to fix the torn poster before the science fair."},{"choice":"boastful","category":"incorrect trait","reason":"A boastful person brags about themselves. The story shows Lena working hard to help her team, not talking about how great she is."},{"choice":"impatient","category":"incorrect trait","reason":"An impatient person would get frustrated or give up when the poster tears. Lena stays calm, which shows she is patient and focused on solving the problem."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["story elements","character","setting","plot"],"standards":["RL.2-6.3"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-story-elements","sequence":136,"skillIds":[],"standardIds":["RL.2-6.3"]}},{"id":"reading-comprehension-story-elements-q0137","version":3,"contentHash":"sha256:3bd4f1509c00da45616c25ae87978ccff2ff4272ca1c024edd7b401b39d5eb5e","question":"Read the story. Grade 5 foundation story: Mateo was at the school bus line when a younger student dropped a folder and papers scattered. Mateo Mateo stepped out of line, gathered the papers, and helped sort them by subject. In the end, the younger student smiled and found the missing homework.\n\nWhat is the story's main problem?","choices":["Mateo wants to leave the setting before anything happens.","a younger student dropped a folder and papers scattered","Mateo cannot remember anyone's name.","The story has no problem to solve."],"correct":1,"studyAid":{"definition":"A problem is the complication or challenge a character faces that causes them to take action. It is the 'what went wrong' moment in a story.","example":"A lost set of keys; a rainy day ruining a picnic; a character missing the last bus home.","strategyClue":"Look for the specific event that changes the situation from normal to difficult. Ask yourself: 'What happened that forced the main character to do something?'","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: a younger student dropped a folder and papers scattered. The main problem is the conflict or difficulty that triggers the events in a story. In this case, the papers falling created an obstacle that required Mateo to help.","incorrect":[{"choice":"Mateo wants to leave the setting before anything happens.","category":"misinterpreted plot point","reason":"This is incorrect because the story describes Mateo choosing to step out of line to help, not trying to escape or leave the situation."},"",{"choice":"Mateo cannot remember anyone's name.","category":"not in text","reason":"This is incorrect because the story never mentions names or Mateo's ability to remember them; this information is not found in the text."},{"choice":"The story has no problem to solve.","category":"misunderstood narrative structure","reason":"This is incorrect because a problem is a central part of any story. Here, the unexpected spill of papers is the specific event that sets the story in motion."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["story elements","character","setting","plot"],"standards":["RL.2-6.3"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-story-elements","sequence":137,"skillIds":[],"standardIds":["RL.2-6.3"]}},{"id":"reading-comprehension-story-elements-q0138","version":3,"contentHash":"sha256:ab126156284a3f4cf2f4a4b8be0f27bc87b965cc8b5df84d2ca549325ea25dd6","question":"Read the story. Grade 5 foundation story: Priya was at the community garden when her bean plants wilted after several hot days. Priya she checked the soil, moved mulch around the stems, and changed the watering schedule. In the end, new green leaves appeared the next week.\n\nWhere does the story mainly take place?","choices":["on a mountain trail","inside a grocery store","the community garden","at a train station"],"correct":2,"studyAid":{"definition":"The setting is the time and place where a story happens. Good readers look for specific nouns that name a location early in the text.","example":"A library setting would mention books or librarians; a beach setting would mention sand or waves.","strategyClue":"Scan the first sentence of the paragraph for location words. The setting is usually introduced immediately to help you picture the scene.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: the community garden. The text explicitly states, 'Priya was at the community garden,' which establishes the primary location for the action of tending to bean plants.","incorrect":[{"choice":"on a mountain trail","category":"mismatched setting details","reason":"The story focuses on watering plants and soil care, which doesn't happen on a mountain trail. This location is not mentioned in the text."},{"choice":"inside a grocery store","category":"mismatched setting details","reason":"While you might buy beans at a store, the story describes the process of growing them, which occurs in a garden, not a store."},"",{"choice":"at a train station","category":"mismatched setting details","reason":"There is no mention of trains, tracks, or travel in the story. The characters are busy with gardening tasks, not waiting for transportation."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["story elements","character","setting","plot"],"standards":["RL.2-6.3"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-story-elements","sequence":138,"skillIds":[],"standardIds":["RL.2-6.3"]}},{"id":"reading-comprehension-story-elements-q0139","version":3,"contentHash":"sha256:99a414cff2aec4717f20055738fff8e8c96362f076b25f033272be0566276696","question":"Read the story. Grade 5 foundation story: Noah was at the music room when he kept missing the same measure during recorder practice. Noah he slowed the song down, clapped the rhythm, and practiced four notes at a time. In the end, he played the measure correctly during rehearsal.\n\nHow is the problem resolved?","choices":["The story ends before the problem is addressed.","Noah decides the problem is impossible.","An adult solves the problem without the character doing anything.","he played the measure correctly during rehearsal"],"correct":3,"studyAid":{"definition":"A story resolution is the part of the narrative where the character's problem is finally solved or the conflict reaches an end.","example":"If a girl cannot reach a toy, the resolution is her climbing a stool to get it. If a boy is lost, the resolution is finding his way home.","strategyClue":"Look for the sentence that describes what happened 'in the end' or after the character took action. Ask yourself: 'What final result shows the problem is gone?'","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: he played the measure correctly during rehearsal. The text explicitly states the solution: Noah slowed the song down, clapped the rhythm, and practiced small chunks, which led to him playing the measure correctly by the end.","incorrect":[{"choice":"The story ends before the problem is addressed.","category":"ignoring text evidence","reason":"This is incorrect because the text clearly describes a resolution. Noah takes specific steps that lead to him playing the measure correctly."},{"choice":"Noah decides the problem is impossible.","category":"misreading character motivation","reason":"Noah does the opposite of giving up; he actively practices and slows the song down to master the difficult measure."},{"choice":"An adult solves the problem without the character doing anything.","category":"falsifying story events","reason":"The story shows Noah working independently to fix his own mistake; no adults are mentioned as helping him resolve the issue."},""]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["story elements","character","setting","plot"],"standards":["RL.2-6.3"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-story-elements","sequence":139,"skillIds":[],"standardIds":["RL.2-6.3"]}},{"id":"reading-comprehension-story-elements-q0140","version":3,"contentHash":"sha256:d6cb1aecef9a9bcb63400ec1f1cb4c00c00007f67dafdeb81321a7806d1602af","question":"Read the story. Grade 5 foundation story: Ari was at the lunch table when two friends argued about who should choose the game at recess. Ari Ari suggested each friend pick one round and then vote on a final round. In the end, both friends agreed and the argument ended.\n\nWhat most likely motivates Ari's actions?","choices":["Ari wanted both friends to feel heard.","Ari wants to make the problem worse.","Ari hopes nobody notices the problem.","Ari is trying to avoid helping anyone."],"correct":0,"studyAid":{"definition":"To find a character's motivation, look at what they do and why they do it. Ask yourself, 'What does the character want to achieve with this action?'","example":"A character shares their lunch because they are kind. A character hides a broken vase because they are afraid of getting in trouble.","strategyClue":"Look at the specific solution the character proposed and ask yourself: 'Does this action help or hurt the people involved?' Then, identify the positive or negative goal behind that outcome.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: Ari wanted both friends to feel heard. Ari's suggestion to let both friends take turns and vote shows a desire for fairness and compromise, ensuring both parties had an equal say in the decision.","incorrect":["",{"choice":"Ari wants to make the problem worse.","category":"misinterpreting character motives","reason":"Ari's suggestion to vote and compromise is a way to solve the argument, not make it worse. Making the problem worse would involve taking sides or fueling the disagreement."},{"choice":"Ari hopes nobody notices the problem.","category":"ignoring story evidence","reason":"Ari directly addresses the problem by proposing a solution. Someone who hopes nobody notices would typically avoid the situation entirely rather than stepping in to mediate."},{"choice":"Ari is trying to avoid helping anyone.","category":"misreading character actions","reason":"By offering a way for the friends to resolve their conflict, Ari is actively helping them. Staying out of it would be avoiding helping, but Ari chose to intervene with a helpful plan."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["story elements","character","setting","plot"],"standards":["RL.2-6.3"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-story-elements","sequence":140,"skillIds":[],"standardIds":["RL.2-6.3"]}},{"id":"reading-comprehension-story-elements-q0141","version":3,"contentHash":"sha256:f739bff515bc4c55203700456a26f1bf99183d24fb8f7853ba194d3f45054479","question":"Read the story. Grade 5 foundation story: Sofia was at the school art show when she worried that her painting looked different from everyone else's. Sofia she listened as visitors asked about her unusual colors and bold shapes. In the end, she began to feel proud of her own style.\n\nWhich word best describes Sofia?","choices":["careless","creative","boastful","impatient"],"correct":1,"studyAid":{"definition":"Character traits are the personality qualities shown through what a person does, says, or thinks. To identify a trait, look for evidence in the text that supports your choice.","example":"If a character shares their lunch, they are generous. If a character studies hard for a test, they are studious.","strategyClue":"Look at the character's specific actions and the author's descriptions of their work. Ask yourself what these actions suggest about how the character thinks or feels.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: creative. Sofia's use of 'unusual colors' and 'bold shapes' demonstrates imagination and originality, which are key traits of someone who is creative.","incorrect":[{"choice":"careless","category":"misinterpreted character trait","reason":"Choosing 'unusual colors' on purpose shows intention and skill, not a lack of care. A careless person would have made mistakes, but Sofia was proud of her own style."},"",{"choice":"boastful","category":"misinterpreted character trait","reason":"Sofia worried about her work and felt proud, but the story does not show her bragging to others or acting like she is better than them."},{"choice":"impatient","category":"misinterpreted character trait","reason":"There is no evidence in the story that Sofia was in a rush. She took the time to listen to visitors and reflect on her own work."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["story elements","character","setting","plot"],"standards":["RL.2-6.3"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-story-elements","sequence":141,"skillIds":[],"standardIds":["RL.2-6.3"]}},{"id":"reading-comprehension-story-elements-q0142","version":3,"contentHash":"sha256:0d2e5c9fb0fd69e548d226aac8c66cf037e0b41d3f9df1dbffee5899fe64903e","question":"Read the story. Grade 5 foundation story: Evan was at the soccer field when his team was losing and he had not scored. Evan he passed to a teammate who had a clear shot instead of kicking from a bad angle. In the end, the teammate scored and the team cheered together.\n\nWhat is the story's main problem?","choices":["Evan cannot remember anyone's name.","Evan wants to leave the setting before anything happens.","his team was losing and he had not scored","The story has no problem to solve."],"correct":2,"studyAid":{"definition":"The main problem (or conflict) is the struggle or challenge a character faces that they must overcome by the end of the story.","example":"A lost puppy looking for home, a student failing a test they must study for, or two friends arguing over a game.","strategyClue":"Ask yourself: 'What is the main character unhappy or worried about?' Look for sentences describing a negative situation or a goal that is currently blocked.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: his team was losing and he had not scored. The main problem is the challenge or struggle the character faces. In this story, the negative situation on the field created the conflict that Evan had to address.","incorrect":[{"choice":"Evan cannot remember anyone's name.","category":"not in text","reason":"This detail is not mentioned anywhere in the story. Always look for evidence directly stated in the text to identify the problem."},{"choice":"Evan wants to leave the setting before anything happens.","category":"misinterpreted intent","reason":"The story shows Evan working with his team to solve a problem, not trying to escape or leave the soccer field."},"",{"choice":"The story has no problem to solve.","category":"missing conflict","reason":"Every story usually has a conflict or a hurdle. Here, the team losing and Evan missing a goal creates the tension that drives the action."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["story elements","character","setting","plot"],"standards":["RL.2-6.3"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-story-elements","sequence":142,"skillIds":[],"standardIds":["RL.2-6.3"]}},{"id":"reading-comprehension-story-elements-q0143","version":3,"contentHash":"sha256:7d0ec5ec0a6bc07f1dffbea23e6d9be4fe86318f454f752498eee3d4cf077bd2","question":"Read the story. Grade 5 foundation story: Mina was at the hallway before the spelling bee when she felt nervous after hearing older students practice difficult words. Mina she breathed slowly, reviewed her word cards, and remembered how much she had studied. In the end, she walked onto the stage feeling steady.\n\nWhere does the story mainly take place?","choices":["at a train station","inside a grocery store","on a mountain trail","the hallway before the spelling bee"],"correct":3,"studyAid":{"definition":"Setting refers to the time and place where a story's events occur. Authors provide context clues like objects or actions to help readers identify the location.","example":"A story mentioning 'chalkboards and desks' takes place in a classroom; a story with 'sand and waves' takes place at a beach.","strategyClue":"Scan the first paragraph for specific nouns related to a place (like 'hallway' or 'stage') and ignore any options that aren't mentioned in the text.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: the hallway before the spelling bee. The story explicitly states that Mina was in this location while waiting for her competition, as evidenced by her proximity to the spelling bee and the sound of students practicing words.","incorrect":[{"choice":"at a train station","category":"incorrect setting inference","reason":"The story mentions a hallway and a stage for a spelling bee, not a train or a station. Look for words like 'tracks' or 'platform' to support such a setting."},{"choice":"inside a grocery store","category":"incorrect setting inference","reason":"There is no mention of food, shopping carts, or aisles. The action of reviewing word cards suggests an academic setting rather than a place to buy groceries."},{"choice":"on a mountain trail","category":"incorrect setting inference","reason":"A mountain trail would feature outdoor elements like trees or rocks. The story describes an indoor environment with a hallway and a stage."},""]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["story elements","character","setting","plot"],"standards":["RL.2-6.3"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-story-elements","sequence":143,"skillIds":[],"standardIds":["RL.2-6.3"]}},{"id":"reading-comprehension-story-elements-q0144","version":3,"contentHash":"sha256:1c48b7ec63aedeaf79bf97f0a0f85fdd409844b5689a0b68551e3303ef9ce231","question":"Read the story. Grade 5 foundation story: Caleb was at the animal shelter when a shy dog hid whenever visitors came near. Caleb Caleb sat quietly nearby each week and let the dog approach when ready. In the end, the dog eventually rested its head beside him.\n\nHow is the problem resolved?","choices":["the dog eventually rested its head beside him","Caleb decides the problem is impossible.","An adult solves the problem without the character doing anything.","The story ends before the problem is addressed."],"correct":0,"studyAid":{"definition":"A story resolution is the part of the plot where the main character's problem is finally solved or settled.","example":"Problem: A lost cat. Resolution: The cat is found under the porch. Problem: A broken bike. Resolution: A friend helps fix the chain.","strategyClue":"Look at the very end of the passage and identify the specific action that shows the tension or fear has disappeared.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: the dog eventually rested its head beside him. This choice directly identifies the moment the shy dog trusts Caleb, showing how the problem of the dog's shyness is solved through Caleb's patience.","incorrect":["",{"choice":"Caleb decides the problem is impossible.","category":"misreading the narrative","reason":"This does not match the text. Caleb actually remains patient and continues visiting, which leads to a successful outcome."},{"choice":"An adult solves the problem without the character doing anything.","category":"ignoring character action","reason":"The text explains that Caleb's own actions—sitting quietly each week—helped the dog feel safe, rather than an adult intervening."},{"choice":"The story ends before the problem is addressed.","category":"missing key details","reason":"The story does provide a resolution: the dog stops hiding and rests its head beside Caleb, which is the final outcome of their interaction."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["story elements","character","setting","plot"],"standards":["RL.2-6.3"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-story-elements","sequence":144,"skillIds":[],"standardIds":["RL.2-6.3"]}},{"id":"reading-comprehension-story-elements-q0145","version":3,"contentHash":"sha256:0508d5fa45de3dcef620eb9b091ed18ffbb3211feff52239c898768655bcb73e","question":"Read the story. Grade 5 foundation story: Jada was at a rainy field trip when the outdoor scavenger hunt had to be canceled. Jada she helped classmates create an indoor museum hunt using exhibit clues. In the end, the class discovered details they might have missed.\n\nWhat most likely motivates Jada's actions?","choices":["Jada wants to make the problem worse.","She wanted the trip to stay interesting even after plans changed.","Jada hopes nobody notices the problem.","Jada is trying to avoid helping anyone."],"correct":1,"studyAid":{"definition":"Character motivation is the reason a character says, thinks, or does something based on their personality and the current situation.","example":"A student studying hard because they want to pass the test; a person sharing their lunch because they are kind.","strategyClue":"Look at what the character actually does and ask yourself what goal that action helps them achieve. Ask, 'What positive result is the character trying to get by doing this?'","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: She wanted the trip to stay interesting even after plans changed. Jada takes initiative by creating a new activity, which shows she wants to keep her classmates engaged and turn a disappointing situation into a positive one.","incorrect":[{"choice":"Jada wants to make the problem worse.","category":"misinterpreting character intent","reason":"Jada's actions, such as creating a new hunt with clues, are helpful and constructive, not malicious or designed to cause more trouble."},"",{"choice":"Jada hopes nobody notices the problem.","category":"ignoring character action","reason":"Instead of hiding or ignoring the canceled hunt, Jada actively creates a replacement, showing she is addressing the problem rather than trying to pretend it doesn't exist."},{"choice":"Jada is trying to avoid helping anyone.","category":"contradictory character behavior","reason":"The text explicitly states that Jada helped her classmates, which directly contradicts the idea that she is trying to avoid helping."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["story elements","character","setting","plot"],"standards":["RL.2-6.3"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-story-elements","sequence":145,"skillIds":[],"standardIds":["RL.2-6.3"]}},{"id":"reading-comprehension-story-elements-q0146","version":3,"contentHash":"sha256:91e66acfe54f374fe3de80780eb8df449be6f22e3cb5567a29037fccf8a68c50","question":"Read the story. Grade 5 foundation story: Omar was at the computer lab when his slideshow disappeared when the program froze. Omar he checked the autosave folder and rebuilt two missing slides from his notes. In the end, his presentation was ready before class ended.\n\nWhich word best describes Omar?","choices":["boastful","careless","determined","impatient"],"correct":2,"studyAid":{"definition":"To identify a character's traits, look at their actions, what they say, and how they react when they face a challenge.","example":"If a character helps others, they are kind. If a character does not give up on a hard puzzle, they are persistent.","strategyClue":"Look at the actions Omar took after the program crashed. Ask yourself, 'What does this person's behavior show about their personality?'","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: determined. Omar is determined because he stayed focused on fixing his problem by checking the autosave folder and rebuilding his slides instead of giving up.","incorrect":[{"choice":"boastful","category":"character trait mismatch","reason":"There is no evidence in the story that Omar bragged about his work or talked about himself in a proud way."},{"choice":"careless","category":"character trait mismatch","reason":"Omar showed the opposite of being careless; he took the time to find his files and rewrite his notes to make sure his work was completed correctly."},"",{"choice":"impatient","category":"character trait mismatch","reason":"Someone who is impatient would have stopped working when the program froze, but Omar kept working until his presentation was finished."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["story elements","character","setting","plot"],"standards":["RL.2-6.3"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-story-elements","sequence":146,"skillIds":[],"standardIds":["RL.2-6.3"]}},{"id":"reading-comprehension-story-elements-q0147","version":3,"contentHash":"sha256:8d0b0fe03e1e6ea0a9f5fa00d1633a40dcefaf5b9b5c9537753397f4e4217a6c","question":"Read the story. Grade 5 foundation story: Nora was at the neighborhood sidewalk when an elderly neighbor struggled to carry groceries up the steps. Nora Nora asked permission, carried two light bags, and held the gate open. In the end, the neighbor thanked her and invited her to pick tomatoes later.\n\nWhat is the story's main problem?","choices":["The story has no problem to solve.","Nora wants to leave the setting before anything happens.","Nora cannot remember anyone's name.","an elderly neighbor struggled to carry groceries up the steps"],"correct":3,"studyAid":{"definition":"The 'main problem' in a story is the challenge, struggle, or conflict that a character must face or overcome.","example":"A character is lost in the woods; a girl cannot find her lost dog; a boy struggles to build a birdhouse.","strategyClue":"Look for a sentence describing someone facing a difficulty or trying to get something done. Ask yourself: 'What is making things hard for a character right now?'","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: an elderly neighbor struggled to carry groceries up the steps. A main problem in a story is the conflict or obstacle that a character faces. In this story, the neighbor's struggle to carry bags is the event that prompts Nora to act.","incorrect":[{"choice":"The story has no problem to solve.","category":"missing narrative conflict","reason":"Stories usually rely on a challenge to drive the plot forward. When the neighbor struggled with the groceries, that created a small obstacle for Nora to help with."},{"choice":"Nora wants to leave the setting before anything happens.","category":"contradicts story text","reason":"This is not supported by the text; Nora actually chose to stay and help the neighbor rather than leaving."},{"choice":"Nora cannot remember anyone's name.","category":"unsupported plot detail","reason":"The text does not mention Nora having trouble with names. A story problem must be a struggle actually described in the plot."},""]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["story elements","character","setting","plot"],"standards":["RL.2-6.3"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-story-elements","sequence":147,"skillIds":[],"standardIds":["RL.2-6.3"]}},{"id":"reading-comprehension-story-elements-q0148","version":3,"contentHash":"sha256:0bb5626032e4d0e8657e9c73835eed6308dffe869d66164861a0f90b8e7cd025","question":"Read the story. Grade 5 foundation story: Ben was at the chess club table when he lost three games in a row. Ben he asked his opponent to show the move that trapped his queen. In the end, he used the lesson to avoid the trap in the next game.\n\nWhere does the story mainly take place?","choices":["the chess club table","inside a grocery store","on a mountain trail","at a train station"],"correct":0,"studyAid":{"definition":"The setting of a story is the specific place or environment where the action happens. Authors provide clues within the sentences to tell the reader where the characters are.","example":"If a story mentions 'blackboard' and 'desk,' the setting is likely a classroom. If it mentions 'sand' and 'waves,' the setting is likely a beach.","strategyClue":"Scan the first sentence of the story for a noun phrase that describes a specific location. Look for key items mentioned, like furniture or equipment, that belong to a certain place.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: the chess club table. The text explicitly states that Ben was at the 'chess club table' when he began playing his games, making this the correct setting for the story.","incorrect":["",{"choice":"inside a grocery store","category":"setting inconsistency","reason":"There is no mention of shopping, food, or aisles in the text. The story focuses on chess games, not a store."},{"choice":"on a mountain trail","category":"setting inconsistency","reason":"The story mentions a chess table and opponents, which are found indoors at a club, not while hiking on a trail."},{"choice":"at a train station","category":"setting inconsistency","reason":"While people play games in many places, the text identifies the location as a chess club table, not a transit hub like a train station."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["story elements","character","setting","plot"],"standards":["RL.2-6.3"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-story-elements","sequence":148,"skillIds":[],"standardIds":["RL.2-6.3"]}},{"id":"reading-comprehension-story-elements-q0149","version":3,"contentHash":"sha256:9a34237e4e5ee3ce3467d515bb70a187627c93d288061724e6ac58b2cfdad4e6","question":"Read the story. Grade 5 foundation story: Talia was at the school hallway after dismissal when she found a wallet with lunch money and a student ID. Talia she took it to the office before leaving for practice. In the end, the owner got the wallet back before the buses left.\n\nHow is the problem resolved?","choices":["Talia decides the problem is impossible.","the owner got the wallet back before the buses left","An adult solves the problem without the character doing anything.","The story ends before the problem is addressed."],"correct":1,"studyAid":{"definition":"The resolution of a story is the final part of the plot where the main character's problem or conflict is solved.","example":"If a character loses a key and then finds it under the rug, finding the key is the resolution. If a character is scared of a dog and then makes friends with it, the friendship is the resolution.","strategyClue":"Locate the conflict at the beginning of the text, then scan the final sentences specifically for the outcome that shows the problem being fixed.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: the owner got the wallet back before the buses left. This is the correct resolution because the final sentence of the story explicitly states that the owner received the wallet back before the buses departed.","incorrect":[{"choice":"Talia decides the problem is impossible.","category":"misreading story events","reason":"The story does not say the problem was impossible; instead, Talia successfully takes the wallet to the office to help the owner."},"",{"choice":"An adult solves the problem without the character doing anything.","category":"character role error","reason":"Talia is the one who actively solves the problem by taking the found wallet to the school office herself."},{"choice":"The story ends before the problem is addressed.","category":"ignoring story conclusion","reason":"The final sentence explicitly confirms that the problem of the lost wallet was fully resolved when the owner got it back."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["story elements","character","setting","plot"],"standards":["RL.2-6.3"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-story-elements","sequence":149,"skillIds":[],"standardIds":["RL.2-6.3"]}},{"id":"reading-comprehension-story-elements-q0150","version":4,"contentHash":"sha256:71660f75293643cd2b59b5d80e22b77fb0c564fecf86106ee4ee59c3cf669479","question":"Read the story. Grade 5 foundation story: Diego was at the creek behind the park when he saw that stepping stones had shifted after heavy rain. Diego he warned younger children to use the bridge and told a ranger. In the end, the crossing was closed until it could be repaired.\n\nWhat most likely motivates Diego's actions?","choices":["Diego hopes nobody notices the problem.","Diego wants to make the problem worse.","He wanted others to stay safe.","Diego is trying to avoid helping anyone."],"correct":2,"studyAid":{"definition":"To find a character's motivation, look at what they do and say in the story. Their actions provide clues about their internal goals and feelings.","example":"If a character shares their lunch, their motivation is likely kindness. If a character cleans up a mess they didn't make, their motivation is likely responsibility.","strategyClue":"List the actions the character takes in the story, then ask yourself, 'What is the positive result or goal of these actions?'","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"},"explanation":{"correct":"Answer: He wanted others to stay safe. Diego's actions—warning the children to use the bridge and informing a ranger—demonstrate concern for the wellbeing of others and a desire to prevent accidents.","incorrect":[{"choice":"Diego hopes nobody notices the problem.","category":"Contradictory behavior","reason":"If Diego wanted the problem to go unnoticed, he would not have told a ranger or warned the children to stay away from the dangerous crossing."},{"choice":"Diego wants to make the problem worse.","category":"Inconsistent with actions","reason":"By warning children to use the bridge, Diego is actively trying to prevent harm, which is the opposite of making the situation worse."},"",{"choice":"Diego is trying to avoid helping anyone.","category":"Opposite intention","reason":"Diego took specific, helpful steps by reporting the issue and protecting younger children, showing that he was intentionally trying to help."}]},"metadata":{"gradeLevels":[6],"difficultyByGrade":{"6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["story elements","character","setting","plot"],"standards":["RL.2-6.3"],"feedbackFocus":"read the whole prompt, find the exact evidence, and choose the answer that best matches the full text","estimatedTimeSeconds":50,"reviewPriority":"high","sourceSet":"reading-comprehension-story-elements","sequence":150,"skillIds":[],"standardIds":["RL.2-6.3"]}}],"metadata":{"gradesSupported":[3,4,5,6],"difficultiesSupported":["easy","medium","hard"],"selectorPolicy":"grade+difficulty selects exact matches first, with 15 exact-match questions for every supported grade and difficulty"}};
  const bank = window.QUESTION_BANK = window.QUESTION_BANK || {};
  const existing = bank["reading-comprehension-story-elements"];
  if (existing && Array.isArray(existing.questions)) {
    const seen = new Set(existing.questions.map(question => question && question.id));
    chunkSet.questions.forEach(question => {
      if (!seen.has(question && question.id)) existing.questions.push(question);
    });
  } else {
    bank["reading-comprehension-story-elements"] = chunkSet;
  }
})();
